/// Types of NNFWs.
///
/// To check if a nnfw-type is supported in a system, an application may call the API, ml_check_nnfw_availability().
///
/// **Since Tizen:**
/// - 5.5
/// @nodoc
abstract class ml_nnfw_type_e {
